create table public.categorias_financieras (
id uuid DEFAULT gen_random_uuid() NOT NULL,
salon_id uuid NOT NULL,
nombre text NOT NULL,
tipo text NOT NULL,
descripcion text,
sistema boolean DEFAULT false NOT NULL,
estado text DEFAULT 'ACTIVA'::text NOT NULL,
creado_por uuid,
creado_en timestamp with time zone DEFAULT now() NOT NULL,
actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
primary key(id)
);
create table public.movimientos_financieros (
id uuid DEFAULT gen_random_uuid() NOT NULL,
salon_id uuid NOT NULL,
sucursal_id uuid,
caja_sesion_id uuid,
categoria_id uuid,
tipo text NOT NULL,
origen text NOT NULL,
metodo_pago text,
concepto text NOT NULL,
descripcion text,
monto numeric NOT NULL,
referencia text,
fecha_movimiento timestamp with time zone DEFAULT now() NOT NULL,
estado text DEFAULT 'APLICADO'::text NOT NULL,
venta_id uuid,
compra_id uuid,
abono_cuenta_pagar_id uuid,
venta_pago_id uuid,
movimiento_caja_id uuid,
movimiento_origen_id uuid,
observaciones text,
creado_por uuid,
anulado_por uuid,
motivo_anulacion text,
fecha_anulacion timestamp with time zone,
creado_en timestamp with time zone DEFAULT now() NOT NULL,
actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
cuenta_cobrar_abono_pago_id uuid,
primary key(id)
);
create table public.plataforma_suscripciones (
salon_id uuid NOT NULL,
estado text DEFAULT 'ACTIVO'::text NOT NULL,
vence_el date,
cuota numeric DEFAULT 0 NOT NULL,
moneda text DEFAULT 'NIO'::text NOT NULL,
motivo text,
actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
primary key(salon_id)
);
create table public.salones (
id uuid DEFAULT gen_random_uuid() NOT NULL,
nombre text NOT NULL,
nombre_comercial text,
telefono text,
whatsapp text,
correo text,
direccion text,
estado text DEFAULT 'ACTIVO'::text NOT NULL,
fecha_registro timestamp with time zone DEFAULT now() NOT NULL,
actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
primary key(id)
);
create table public.sucursales (
id uuid DEFAULT gen_random_uuid() NOT NULL,
salon_id uuid NOT NULL,
nombre text NOT NULL,
telefono text,
whatsapp text,
correo text,
direccion text,
es_principal boolean DEFAULT false NOT NULL,
estado text DEFAULT 'ACTIVA'::text NOT NULL,
fecha_registro timestamp with time zone DEFAULT now() NOT NULL,
actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
primary key(id)
);
create table public.trabajadores (
id uuid DEFAULT gen_random_uuid() NOT NULL,
salon_id uuid NOT NULL,
sucursal_id uuid,
usuario_id uuid,
nombre_completo text NOT NULL,
telefono text,
correo text,
direccion text,
especialidad text,
descripcion text,
fecha_nacimiento date,
fecha_ingreso date,
color_calendario text DEFAULT '#6F8F83'::text NOT NULL,
tipo_comision text DEFAULT 'PORCENTAJE'::text NOT NULL,
comision_general numeric DEFAULT 0 NOT NULL,
permite_citas boolean DEFAULT true NOT NULL,
estado text DEFAULT 'ACTIVO'::text NOT NULL,
observaciones text,
fecha_registro timestamp with time zone DEFAULT now() NOT NULL,
actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
modalidad_pago text DEFAULT 'SOLO_COMISION'::text NOT NULL,
salario_fijo numeric DEFAULT 0 NOT NULL,
frecuencia_pago text DEFAULT 'MENSUAL'::text NOT NULL,
primary key(id)
);
alter table movimientos_financieros add constraint movimientos_financieros_origen_check check (origen in ('VENTA','PAGO_PROVEEDOR','COMISION_POS','MOVIMIENTO_CAJA','MANUAL','AJUSTE','OTRO'));
